/* ---------- SOUND MATCH: captured sound (slot A) → editable FM patch ---------- */
function fmRateForTime(sec,fromL,toL){var best=50,bd=1e9;for(var r=0;r<=99;r++){var t=fmEnvTime(r,fromL,toL);var d=Math.abs(Math.log((t+0.002)/(sec+0.002)));if(d<bd){bd=d;best=r;}}return best;}
