    var tot=fr.map(function(m){var e=0;for(var j=1;j<m.length;j++)e+=m[j]*m[j];return Math.sqrt(e);}),pk=0,pki=0;tot.forEach(function(v,i){if(v>pk){pk=v;pki=i;}});
