    /* 3) envelope timings from the overall amplitude curve */
    var dt=hop/sr,att=pki*dt,thr=pk*0.5,i50=pki;while(i50<tot.length-1&&tot[i50]>thr)i50++;var dec50=(i50-pki)*dt,sus=tot[Math.min(tot.length-1,pki+Math.round(0.6/dt))]/pk||0,lastI=tot.length-1;while(lastI>pki&&tot[lastI]<pk*0.03)lastI--;
